// @effect-diagnostics nodeBuiltinImport:off - a build script that edits one file.
/**
 * Runs after Better Auth's CLI rewrites src/auth/schema.ts: marks the file as
 * generated and allows the `new Date()` defaults Drizzle needs there.
 */
import * as NodeFS from "node:fs";

const file = new URL("../src/auth/schema.ts", import.meta.url);
const header =
  "// @effect-diagnostics globalDate:off - generated by `vp run auth:schema`; Drizzle column defaults need Date.\n";
const source = NodeFS.readFileSync(file, "utf8");
if (!source.startsWith(header)) NodeFS.writeFileSync(file, header + source);
